def main():
    d = pymupdf.open(SRC + f"/{FID}.pdf"); out = []
    for m in M:
        imgs = {}
        for pno in set(p for p, _ in m["pick"]):
            lst = sorted(d[pno - 1].get_image_info(xrefs=True), key=lambda i: -(i["bbox"][2] - i["bbox"][0]) * (i["bbox"][3] - i["bbox"][1]))[:7]
            for k, i in enumerate(lst):
                if i["bbox"][2] - i["bbox"][0] < 100 or not i["xref"]: continue
                imgs[(pno, k)] = i["xref"]
        paths = []
        for n, key in enumerate(m["pick"]):
            try:
                pxi = px_image(d, imgs[key])
                pth = save_image(pxi, f"79bike/{m['id']}-{n+1}")
                if pth and pth not in paths: paths.append(pth)
            except Exception as e: print("img", m["id"], key, e)
        out.append({"id": "79bike-" + m["id"], "cat": "ebike-enduro", "brand": "79BIKE", "name": "Электро-эндуро 79BIKE " + m["name"], "sku": m["name"], "images": paths, "src": FNAME, "page": m["pages"][0],
                    "power_kw": m["power_kw"], "battery_v": m["v"], "battery_ah": m["ah"], "battery_wh": m["v"] * m["ah"], "battery_type": "Литиевый", "top_speed": m["speed"], "range_km": m["rng"],
                    "weight_kg": m["weight"], "max_load_kg": m["load"], "brakes": "Дисковые", "extra": m["rows"],
                    "desc": "Электрический внедорожный мотоцикл (эндуро). Цена в каталоге не указана."})
    json.dump(out, open(OUT + "/bike79.json", "w"), ensure_ascii=False)
    print(len(out), [len(p["images"]) for p in out])

main()
